args.new_string:
export const dynamic = 'force-dynamic';

export default function Home() {
  const timestamp = new Date().toISOString();
  const formattedTimestamp = new Date().toLocaleString('en-US', {
    dateStyle: 'full',
    timeStyle: 'long'
  });

  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>This timestamp is generated on the server for each request:</p>
      <div style={{ marginTop: '20px', padding: '20px', background: '#f5f5f5', borderRadius: '8px' }}>
        <p><strong>ISO Format:</strong> {timestamp}</p>
        <p><strong>Formatted:</strong> {formattedTimestamp}</p>
      </div>
      <p style={{ marginTop: '20px', fontSize: '14px', color: '#666' }}>
        Refresh the page to see the timestamp update with each request.
      </p>
    </main>
  );
}

